begin;
select plan(24);
select has_table('public','training_quiz_attempts','quiz attempts table exists');
select has_table('public','training_quiz_attempt_answers','attempt answers table exists');
select has_table('public','training_course_completions','course completions table exists');
select has_column('public','training_quiz_attempts','start_idempotency_key','start idempotency is persisted');
select has_column('public','training_quiz_attempts','submit_request_sha256','submission payload digest is persisted');
select has_column('public','training_quiz_attempt_answers','correct','server scoring evidence is persisted');
select has_column('public','training_course_completions','passing_attempt_id','completion references its passing attempt');
select has_pk('public','training_quiz_attempts','attempts have a primary key');
select has_pk('public','training_quiz_attempt_answers','answers have a primary key');
select has_pk('public','training_course_completions','completions have a primary key');
select has_index('public','training_quiz_attempts','training_quiz_attempts_one_open_idx','one-open-attempt partial index exists');
select has_index('public','training_quiz_attempts','training_quiz_attempts_employee_version_idx','employee attempt reporting index exists');
select has_index('public','training_course_completions','training_course_completions_employee_idx','employee completion reporting index exists');
select ok((select relrowsecurity from pg_catalog.pg_class where oid='public.training_quiz_attempts'::regclass),'attempt RLS is enabled');
select ok((select relrowsecurity from pg_catalog.pg_class where oid='public.training_quiz_attempt_answers'::regclass),'answer RLS is enabled');
select ok((select relrowsecurity from pg_catalog.pg_class where oid='public.training_course_completions'::regclass),'completion RLS is enabled');
select ok(not has_table_privilege('service_role','public.training_quiz_attempts','select') and not has_table_privilege('anon','public.training_quiz_attempts','select') and not has_table_privilege('authenticated','public.training_quiz_attempts','select'),'attempt direct reads are revoked');
select ok(not has_table_privilege('service_role','public.training_quiz_attempt_answers','select') and not has_table_privilege('anon','public.training_quiz_attempt_answers','select') and not has_table_privilege('authenticated','public.training_quiz_attempt_answers','select'),'answer direct reads are revoked');
select ok(not has_table_privilege('service_role','public.training_course_completions','select') and not has_table_privilege('anon','public.training_course_completions','select') and not has_table_privilege('authenticated','public.training_course_completions','select'),'completion direct reads are revoked');
select is((select count(*)::integer from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('start_training_final_quiz_attempt','get_training_final_quiz_attempt','get_training_final_assessment_status','submit_training_final_quiz_attempt')),4,'all Final Quiz RPCs exist');
select is((select count(*)::integer from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('start_training_final_quiz_attempt','get_training_final_quiz_attempt','get_training_final_assessment_status','submit_training_final_quiz_attempt') and p.prosecdef),4,'all Final Quiz RPCs are SECURITY DEFINER');
select is((select count(*)::integer from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('start_training_final_quiz_attempt','get_training_final_quiz_attempt','get_training_final_assessment_status','submit_training_final_quiz_attempt') and p.proconfig @> array['search_path=""']),4,'all Final Quiz RPCs have empty search path');
select ok(has_function_privilege('service_role','public.start_training_final_quiz_attempt(uuid,uuid,uuid,uuid,text,uuid)','execute') and not has_function_privilege('authenticated','public.start_training_final_quiz_attempt(uuid,uuid,uuid,uuid,text,uuid)','execute'),'start RPC is service-role-only');
select ok(has_function_privilege('service_role','public.submit_training_final_quiz_attempt(uuid,uuid,uuid,uuid,uuid,uuid,jsonb)','execute') and not has_function_privilege('anon','public.submit_training_final_quiz_attempt(uuid,uuid,uuid,uuid,uuid,uuid,jsonb)','execute'),'submit RPC is service-role-only');
select * from finish();
rollback;
